"use client";

import { MorphingDialog } from "@/components/application/animations/expanded/controls/morphing-dialog";

export default function Example() {
  return (
    <MorphingDialog
      title={"Carbon Tempo Trainer"}
      subtitle={"Daily Training Shoe"}
      image={{
        "src": "/assets/zeus/hero_run_02.jpg",
        "alt": "Carbon Tempo Trainer in motion"
      }}
      price={"$164"}
      badge={"NEW"}
      actionLabel={"Add to cart"}
      duration={0.65}
    >
      {"Open a product card without losing your place. The image and title travel into this expanded view, with room for a description and an action. Replace the sample product data with your own catalog to make the experience yours."}
    </MorphingDialog>
  );
}

