"use client";
import { useId, useRef, type ReactNode } from "react";
import { AnimatePresence, LayoutGroup, motion } from "motion/react";
import {
  ControlStyles,
  controlVariables,
  useControlDialog,
  useControlTransition,
  useControlValue,
  type ControlAppearance,
} from "./control-shared";
export interface MorphingDialogProps extends ControlAppearance {
  title: string;
  subtitle?: string;
  image: { src: string; alt: string };
  price?: ReactNode;
  badge?: string;
  children: ReactNode;
  actionLabel?: string;
  onAction?: () => void;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  closeLabel?: string;
}
export function MorphingDialog({
  title,
  subtitle,
  image,
  price,
  badge,
  children,
  actionLabel,
  onAction,
  open,
  defaultOpen = false,
  onOpenChange,
  closeLabel = "Close details",
  ...appearance
}: MorphingDialogProps) {
  const [isOpen, setOpen] = useControlValue(open, defaultOpen, onOpenChange);
  const initiallyOpen = useRef(isOpen);
  const id = useId();
  const transition = useControlTransition(appearance.duration);
  const trigger = useRef<HTMLButtonElement>(null);
  const dialog = useControlDialog(isOpen, setOpen, appearance.duration, trigger);
  const media = () => (
    <motion.div layoutId={`${id}-image`} className="z-mc-product-image" transition={transition}>
      <img src={image.src} alt={image.alt} />
      {badge && (
        <motion.span layoutId={`${id}-badge`} className="z-mc-product-badge">
          {badge}
        </motion.span>
      )}
    </motion.div>
  );
  const copy = (expanded: boolean) => (
    <div className="z-mc-product-copy">
      <motion.h2
        id={expanded ? `${id}-title` : undefined}
        layoutId={`${id}-title`}
        transition={transition}
      >
        {title}
      </motion.h2>
      {subtitle && (
        <motion.p layoutId={`${id}-subtitle`} transition={transition}>
          {subtitle}
        </motion.p>
      )}
      {price != null && (
        <motion.div layoutId={`${id}-price`} className="z-mc-product-price" transition={transition}>
          {price}
        </motion.div>
      )}
      {expanded ? (
        <button
          autoFocus
          type="button"
          className="z-mc-close"
          aria-label={closeLabel}
          onClick={() => setOpen(false)}
        >
          ×
        </button>
      ) : (
        <span className="z-mc-product-open" aria-hidden="true">
          ↗
        </span>
      )}
    </div>
  );
  return (
    <LayoutGroup id={id}>
      <ControlStyles />
      <div
        className={`z-mc ${appearance.className ?? ""}`}
        style={controlVariables({ background: "#e8e8e8", color: "#111111", ...appearance })}
      >
        <motion.button
          ref={trigger}
          type="button"
          className="z-mc-product-card"
          aria-label={`View ${title} details`}
          aria-haspopup="dialog"
          aria-expanded={isOpen}
          style={{ visibility: isOpen ? "hidden" : "visible" }}
          onClick={() => setOpen(true)}
        >
          {!isOpen && (
            <motion.div layoutId={`${id}-surface`} transition={transition}>
              {media()}
              {copy(false)}
            </motion.div>
          )}
          {isOpen && <div style={{ height: 385 }} aria-hidden="true" />}
        </motion.button>
        <dialog
          open={initiallyOpen.current || undefined}
          ref={dialog}
          className="z-mc z-mc-native-dialog"
          aria-labelledby={`${id}-title`}
          onClick={(e) => {
            if (e.target === e.currentTarget) setOpen(false);
          }}
        >
          <motion.div
            className="z-mc-dialog-shade"
            aria-hidden="true"
            initial={false}
            animate={{ opacity: isOpen ? 1 : 0 }}
            transition={transition}
            onClick={() => setOpen(false)}
          />
          <div className="z-mc-dialog-wrap">
            <AnimatePresence initial={false}>
              {isOpen && (
                <motion.div
                  key="product"
                  layoutId={`${id}-surface`}
                  className="z-mc-product-dialog"
                  transition={transition}
                >
                  {media()}
                  {copy(true)}
                  <motion.div
                    className="z-mc-product-body"
                    initial={{ opacity: 0, y: 14 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0 }}
                    transition={{ ...transition, delay: Number(transition.duration ?? 0) * 0.25 }}
                  >
                    {children}
                    {actionLabel && (
                      <button type="button" className="z-mc-product-action" onClick={onAction}>
                        {actionLabel}
                      </button>
                    )}
                  </motion.div>
                </motion.div>
              )}
            </AnimatePresence>
          </div>
        </dialog>
      </div>
    </LayoutGroup>
  );
}
